# Let me check all colors for hollow rectangles

def find_hollow_rectangles(grid):
    """Find all complete hollow rectangles"""
    hollow_patterns = []

    # 3x3 hollow squares
    for color in set(all_cells):
        for r in range(len(grid)-2):
            for c in range(len(grid[0])-2):
                # Check hollow 3x3
                if (grid[r][c] == color and grid[r][c+2] == color and
                    grid[r+2][c] == color and grid[r+2][c+2] == color):
                    # Check corners are same color and edges are same color
                    if (grid[r+1][c+1] != color and  # center is different
                        grid[r+1][c] == color and    # left edge
                        grid[r+1][c+2] == color and  # right edge
                        grid[r][c+1] == color and    # top edge
                        grid[r+2][c+1] == color):    # bottom edge
                        hollow_patterns.append({
                            'type': '3x3_hollow',
                            'color': color,
                            'top_left': (r, c),
                            'inner': grid[r+1][c+1]
                        })

    # Check for 2x4, 2x3, 4x2, etc. hollow rectangles
    # For 2xN hollow: 2 rows, N columns where outer frame has different color
    for r in range(len(grid)-1):
        for c in range(len(grid[0])):
            if grid[r][c]:
                for R in range(r+1, len(grid)):
                    for C in range(c+1, len(grid[0])):
                        # Check hollow rectangle
                        if (grid[r][c] == grid[r][C] == grid[R][c] == grid[R][C] and
                            grid[r+1][c+1] != grid[r][c] and
                            R - r <= 2 and C - c <= 4):
                            # Check it's hollow
                            frame = grid[r][c]
                            is_hollow = True
                            for i in range(1, R-r):
                                for j in range(1, C-c):
                                    if grid[r+i][c+j] == frame:
                                        is_hollow = False
                                        break
                                    if i == R or j == C:
                                        if grid[r+i][c+j] != frame:
                                            is_hollow = False
                                            break
                            if is_hollow:
                                hollow_patterns.append({
                                    'type': 'rect_hollow',
                                    'color': frame,
                                    'inner': grid[r+1][c+1]
                                })

    return hollow_patterns

grid = grid
all_cells = [row[r] for row in grid for r in row]
print(f"All cells: {set(all_cells)}")

hollows = find_hollow_rectangles(grid)
print(f"\nFound {len(hollows)} hollow patterns:")
for h in hollows:
    print(f"  {h}")

